  <input id="spectrumViewInput" type="checkbox" onchange="toggle_spectrumView(this.checked)">
  <span>View: Organic IR window (4000–400 cm⁻¹)</span>
</label>
<span style="font-size:10.5px;color:#555;line-height:1.4">Drag the round handle on the axis, or hover / click a coloured region.</span>
<button onclick="showPopup('Key insight','Wavelength, wavenumber and photon energy are one variable seen three ways: &#957;&#771; = 1/&#955; and E = hc&#957;&#771;, so moving right on this axis lowers both wavenumber and energy together. The entire practice of IR structure determination lives inside one narrow decade of that axis, 4000 to 400 cm&#8315;&#185; (2.5 to 25 &#181;m).')">Why it matters</button>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var W = 1100, H = 400;
  var BT = 74, BB = 206, AXIS_Y = 206;
  var FONT = 'Helvetica, Arial, sans-serif';

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var gBand = draw.group(), gAxis = draw.group(), gAnno = draw.group(),
      gArrow = draw.group(), gMarker = draw.group(), gCard = draw.group(), gDrag = draw.group();

  /* ---------- helpers ---------- */
  var SUP = { '-': '\u207B', '0': '\u2070', '1': '\u00B9', '2': '\u00B2', '3': '\u00B3',
              '4': '\u2074', '5': '\u2075', '6': '\u2076', '7': '\u2077', '8': '\u2078', '9': '\u2079' };
  function sup(n) { return String(n).split('').map(function (c) { return SUP[c] || c; }).join(''); }
