// @FIGURE_CODE_BEGIN
(function () {
  var W = 1100, H = 500;
  var BT = 74, BB = 206, AXIS_Y = 206;
  var ELBOW_Y = 292, BAR_Y = 398, BAR_H = 90;
  var FONT = 'Helvetica, Arial, sans-serif';
  var FS = 1;                                   // global font magnifier (readability)

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);

  var gArrow = draw.group(), gBand = draw.group(), gAxis = draw.group(),
      gAnno = draw.group(), gMarker = draw.group(), gCard = draw.group(), gDrag = draw.group();

  /* ---------- text helpers ---------- */
  var SUP = { '-': '\u207B', '0': '\u2070', '1': '\u00B9', '2': '\u00B2', '3': '\u00B3',
              '4': '\u2074', '5': '\u2075', '6': '\u2076', '7': '\u2077', '8': '\u2078', '9': '\u2079' };
  function sup(n) { return String(n).split('').map(function (c) { return SUP[c] || c; }).join(''); }
  function sci(v, d) {
    if (!isFinite(v) || v === 0) return '0';
    var e = Math.floor(Math.log10(v)), m = v / Math.pow(10, e);
    if (m >= 9.995) { m = 1; e += 1; }
    return m.toFixed(d == null ? 1 : d) + ' \u00D7 10' + sup(e);
  }
  function txtU(g, s, x, y, size, o) {           // size already in user units
    o = o || {};
    var t = g.plain(s);
    t.font({ family: FONT, size: size, weight: o.weight || 'normal', style: o.style || 'normal' });
    t.attr({ x: x, y: y, 'text-anchor': o.anchor || 'middle', fill: o.fill || '#1a1a1a' });
    if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.halo, 'stroke-linejoin': 'round' });
    if (o.pe === false) t.attr('pointer-events', 'none');
    return t;
  }
  function txt(g, s, x, y, base, o) { return txtU(g, s, x, y, base * FS, o); }
  function fitSize(s, base, maxW) {              // shrink so the string fits maxW user units
    var want = base * FS;
    var need = maxW / (0.56 * Math.max(1, String(s).length));
    return Math.max(9, Math.min(want, need));
  }
  function wave(x, y0, y1, amp, n) {
    var h = (y1 - y0) / n, s = '';
    for (var i = 0; i < n; i++) {
      var ym = y0 + h * (i + 0.5), ye = y0 + h * (i + 1);
      s += ' Q ' + (x + (i % 2 === 0 ? -amp : amp)) + ',' + ym + ' ' + x + ',' + ye;
    }
    return s;
  }
  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

  /* ---------- responsive font scale ---------- */
  function updateFS(w, h) {
    var c = document.getElementById('container');
    if (!w || !h) {
      var cs = getComputedStyle(c);
      var padX = (parseFloat(cs.paddingLeft) || 0) + (parseFloat(cs.paddingRight) || 0);
      var padY = (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
      w = Math.max(1, c.clientWidth - padX);
      h = Math.max(1, c.clientHeight - padY);
    }
    var ppu = Math.min(w / W, h / H);            // rendered px per user unit
    if (!isFinite(ppu) || ppu <= 0) ppu = 0.5;
    FS = clamp(11.8 / (12 * ppu), 1, 1.7);       // keep the smallest label ≥ ~11.8 px
  }

  /* ---------- state & mapping ---------- */
  var state = { logL: -3.4, mode: 'full', showMarker: false };
  function dom() { return state.mode === 'full' ? [-5.31, -0.93] : [-3.602, -2.602]; }
  function xOf(l) { return state.mode === 'full' ? 90 + (l + 5) * 240 : 45 + (l + 3.602) * 1010; }
  function lOf(x) { return state.mode === 'full' ? (x - 90) / 240 - 5 : (x - 45) / 1010 - 3.602; }

  /* ---------- data ---------- */
  var FULL_SEGS = [
    { name: 'Ultraviolet', short: 'Ultraviolet', a: -5.31, b: -4.588, fill: '#ab86c0', lines: ['Ultraviolet'], tornLeft: true,
      tip: '\u03BB shorter than ~2.6\u00D710\u207B\u2075 cm (260 nm) \u2014 electronic transitions.',
      popup: 'Ultraviolet photons carry enough energy (hundreds of kJ/mol) to promote electrons between molecular orbitals. This is the realm of UV\u2013vis spectroscopy and of bond-breaking photochemistry, not of vibrations.' },
    { name: 'Visible', short: 'Visible', a: -4.588, b: -4.173, fill: '#d8a5cf', lines: ['Visible'],
      tip: '380\u2013780 nm \u2014 electronic transitions in conjugated systems; the colours we see.',
      popup: 'The visible window is a very thin slice of the spectrum, roughly 3.8\u00D710\u207B\u2075 to 7.8\u00D710\u207B\u2075 cm. Absorption here also comes from electronic transitions, but only in highly conjugated molecules whose orbital gaps have narrowed into this range.' },
    { name: 'Near infrared', short: 'Near IR', a: -4.173, b: -3.602, fill: '#f9d3e3', lines: ['Near', 'infrared'],
      tip: '0.78\u20132.5 \u00B5m \u2014 overtones and combination bands; weak vibrational absorptions.',
      popup: 'Near-IR photons excite overtones (first, second harmonics) and combinations of fundamental vibrations. These bands are weak, which is why analytical near-IR is used for bulk quantitation rather than structure determination.' },
    { name: 'Infrared', short: 'Infrared', a: -3.602, b: -2.602, fill: '#f7bfd9', lines: ['Infrared'],
      tip: '2.5\u201325 \u00B5m = 4000\u2013400 cm\u207B\u00B9 \u2014 fundamental bond stretches and bends.',
      popup: 'This single decade of wavelength is the IR region an ordinary spectrometer scans. Photon energies of roughly 5\u201348 kJ/mol match the fundamental stretching and bending frequencies of covalent bonds, which is exactly why the IR spectrum reports on functional groups.' },
    { name: 'Far infrared', short: 'Far IR', a: -2.602, b: -1.602, fill: '#fdeef6', lines: ['Far infrared'],
      tip: '25\u2013250 \u00B5m = 400\u201340 cm\u207B\u00B9 \u2014 heavy-atom and skeletal bending modes.',
      popup: 'Far-IR photons are too weak to excite the stretches of light-atom bonds, but they do drive low-frequency skeletal bends and vibrations involving heavy atoms. Routine organic spectrometers stop at 400 cm\u207B\u00B9, at the start of this region.' },
    { name: 'Microwaves', short: 'Microwaves', a: -1.602, b: -0.93, fill: '#dee1ce', lines: ['Microwaves'], tornRight: true,
      tip: '\u03BB longer than ~250 \u00B5m \u2014 molecular rotations.',
      popup: 'Microwave photons carry only a fraction of a kJ/mol, enough to change a molecule\u2019s rotational state but not its vibrations. The spectrum keeps going to the right (radio waves), which is what the torn edge indicates.' }
  ];

  var WIN_SEGS = [
    { name: 'Functional group region', short: 'Functional gp.', a: -3.602, b: -3.176, fill: '#f7bfd9',
      lines: [{ s: 'Functional group region', f: 16 }, { s: '4000\u20131500 cm\u207B\u00B9', f: 14, fill: '#4a4a4a' }],
      tip: '4000\u20131500 cm\u207B\u00B9 \u2014 O\u2013H, N\u2013H, C\u2013H, C\u2261N, C\u2261C, C=O stretches.',
      popup: 'Between 4000 and 1500 cm\u207B\u00B9 each absorption can usually be assigned to one bond type, because the stretching frequency of a light-atom bond depends mainly on that bond. This is where you read functional groups straight off the spectrum.' },
    { name: 'Fingerprint region', short: 'Fingerprint', a: -3.176, b: -2.602, fill: '#f9d3e3',
      lines: [{ s: 'Fingerprint region', f: 16 }, { s: '1500\u2013400 cm\u207B\u00B9', f: 14, fill: '#4a4a4a' }],
      tip: '1500\u2013400 cm\u207B\u00B9 \u2014 coupled skeletal vibrations, unique to the whole molecule.',
      popup: 'Below 1500 cm\u207B\u00B9 the vibrations involve the whole carbon skeleton and are strongly coupled, so individual peaks resist assignment. The pattern as a whole is, however, unique to a compound \u2014 hence \u201Cfingerprint\u201D.' }
  ];

  /* ---------- energy arrow ---------- */
  var grad = draw.gradient('linear', function (add) {
    add.stop(0, '#c33a1e'); add.stop(0.45, '#ef8a4c'); add.stop(1, '#fdf3a6');
  });
  grad.from(0, 0).to(1, 0);

  function drawArrow() {
    gArrow.clear();
    gArrow.polygon('315,32 372,2 372,15 862,15 862,49 372,49 372,62')
      .fill(grad).stroke({ color: '#333', width: 1 });
    txt(gArrow, 'Energy', 617, 32 + 18 * FS * 0.35, 18, { weight: 'bold', halo: 3.5, pe: false });
    gArrow.rect(547, 60).move(315, 2).fill('#fff').opacity(0)
      .attr('pointer-events', 'all').css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip('Photon energy rises to the left: E = hc/\u03BB = hc\u03BD\u0303', e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () {
        showPopup('Energy increases to the left',
          'Because E = hc/\u03BB, short wavelengths on the left carry the most energy per photon and long wavelengths on the right the least. Wavenumber \u03BD\u0303 = 1/\u03BB is directly proportional to energy, which is why chemists plot IR spectra in cm\u207B\u00B9.');
      });
  }

  /* ---------- band ---------- */
  function drawBand() {
    gBand.clear();
    var segs = state.mode === 'full' ? FULL_SEGS : WIN_SEGS;
    segs.forEach(function (s) {
      var xa = xOf(s.a), xb = xOf(s.b), d;
      if (s.tornLeft) d = 'M ' + xb + ',' + BT + ' L ' + xa + ',' + BT + wave(xa, BT, BB, 9, 4) + ' L ' + xb + ',' + BB + ' Z';
      else if (s.tornRight) d = 'M ' + xa + ',' + BT + ' L ' + xb + ',' + BT + wave(xb, BT, BB, 9, 4) + ' L ' + xa + ',' + BB + ' Z';
      else d = 'M ' + xa + ',' + BT + ' L ' + xb + ',' + BT + ' L ' + xb + ',' + BB + ' L ' + xa + ',' + BB + ' Z';
      var p = gBand.path(d).fill(s.fill).stroke({ color: '#333', width: 1.1 }).css('cursor', 'pointer');
      p.on('mousemove', function (e) { showTooltip(s.name + ' \u2014 ' + s.tip, e); })
       .on('mouseleave', hideTooltip)
       .on('click', function () { showPopup(s.name, s.popup); });

      var cx = (xa + xb) / 2, avail = Math.abs(xb - xa) - 14, cy = (BT + BB) / 2;
      var lines = s.lines.map(function (L) { return (typeof L === 'string') ? { s: L, f: 16 } : L; });
      if (lines.length === 1) {
        var f1 = fitSize(lines[0].s, lines[0].f, avail);
        txtU(gBand, lines[0].s, cx, cy + f1 * 0.35, f1, { fill: lines[0].fill || '#1a1a1a', pe: false });
      } else {
        var fa = fitSize(lines[0].s, lines[0].f, avail);
        var fb = fitSize(lines[1].s, lines[1].f, avail);
        txtU(gBand, lines[0].s, cx, cy - fa * 0.20, fa, { fill: lines[0].fill || '#1a1a1a', pe: false });
        txtU(gBand, lines[1].s, cx, cy + fb * 1.10, fb, { fill: lines[1].fill || '#1a1a1a', pe: false });
      }
    });
    if (state.mode === 'win') {
      gBand.rect(xOf(-2.602) - xOf(-3.602), BB - BT).move(xOf(-3.602), BT)
        .fill('#ffc83d').opacity(0.12).attr('pointer-events', 'none');
    }
  }

  /* ---------- axis ---------- */
  function drawAxis() {
    gAxis.clear();
    var fsT = 16 * FS, baseY = AXIS_Y + 10 + fsT * 0.85;
    if (state.mode === 'full') {
      gAxis.line(xOf(-5.31), AXIS_Y, xOf(-0.93), AXIS_Y).stroke({ color: '#333', width: 1.1 });
      for (var e = -5; e <= -1; e++) {
        var x = xOf(e);
        gAxis.line(x, AXIS_Y, x, AXIS_Y + 9).stroke({ color: '#333', width: 1.3 });
        txtU(gAxis, '10' + sup(e), x, baseY, fsT, { pe: false });
      }
      txtU(gAxis, '\u03BB', 8, baseY, 15 * FS, { anchor: 'start', style: 'italic', pe: false });
      txtU(gAxis, '(cm)', 8, baseY + 15 * FS * 1.3, 15 * FS, { anchor: 'start', pe: false });
    } else {
      [4000, 3000, 2000, 1500, 1000, 400].forEach(function (v) {
        var x = xOf(-Math.log10(v));
        gAxis.line(x, AXIS_Y, x, AXIS_Y + 9).stroke({ color: '#333', width: 1.3 });
        txtU(gAxis, String(v), x, baseY, fsT, { pe: false });
      });
      txt(gAxis, 'wavenumber \u03BD\u0303 (cm\u207B\u00B9) \u2014 the scale every IR spectrum is plotted on',
        550, baseY + 15 * FS * 1.7, 15, { fill: '#333', pe: false });
      txt(gAxis, '2.5 \u00B5m', xOf(-3.602) + 6, BT - 10, 14, { fill: '#444', anchor: 'start', halo: 3, pe: false });
      txt(gAxis, '25 \u00B5m', xOf(-2.602) - 6, BT - 10, 14, { fill: '#444', anchor: 'end', halo: 3, pe: false });
    }
  }

  /* ---------- leader-line annotations (full view) ---------- */
  function callout(xb, dir, l1, l2, l3, tip) {
    var fs = 16 * FS, lh = fs * 1.32, est = fs * 0.54 * 17;
    var stub = dir > 0 ? xb + fs * 1.8 : xb - fs * 2.0;
    var leftX = dir > 0 ? stub + 8 : stub - est;
    gAnno.polygon((xb - 5) + ',' + (AXIS_Y + 13) + ' ' + (xb + 5) + ',' + (AXIS_Y + 13) + ' ' + xb + ',' + (AXIS_Y + 2))
      .fill('#222');
    gAnno.path('M ' + xb + ',' + (AXIS_Y + 13) + ' L ' + xb + ',' + ELBOW_Y + ' L ' + stub + ',' + ELBOW_Y)
      .fill('none').stroke({ color: '#222', width: 1.2 });
    var y1 = ELBOW_Y + fs * 0.35;
    var a = txtU(gAnno, l1, leftX, y1, fs, { anchor: 'start' });
    txtU(gAnno, l2, leftX + fs * 1.35, y1 + lh, fs, { anchor: 'start', pe: false });
    txtU(gAnno, l3, leftX, y1 + 2 * lh, fs, { anchor: 'start', pe: false });
    a.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip);
  }
  function drawAnno() {
    gAnno.clear();
    if (state.mode !== 'full') return;
